// The only place the interface talks to the shell.
//
// Every call goes through here, typed against the bindings generated from the shell's wire
// types (`src/lib/bindings/`, regenerated by `npm run bindings`). Nothing else in the
// interface imports `invoke`, so the whole surface is one file to read.

import { Channel, invoke } from "@tauri-apps/api/core";

import type { CommandError } from "./bindings/CommandError";
import type { Fix } from "./bindings/Fix";
import type { FixAction } from "./bindings/FixAction";
import type { Grant } from "./bindings/Grant";
import type { GrantDone } from "./bindings/GrantDone";
import type { InitDone } from "./bindings/InitDone";
import type { Issue } from "./bindings/Issue";
import type { NoteSaved } from "./bindings/NoteSaved";
import type { PermissionPage } from "./bindings/PermissionPage";
import type { ProjectDetails } from "./bindings/ProjectDetails";
import type { ProjectMoved } from "./bindings/ProjectMoved";
import type { ProjectSummary } from "./bindings/ProjectSummary";
import type { RevokeDone } from "./bindings/RevokeDone";
import type { RootSaved } from "./bindings/RootSaved";
import type { SwitchDone } from "./bindings/SwitchDone";
import type { SearchHit } from "./bindings/SearchHit";
import type { SearchResults } from "./bindings/SearchResults";
import type { SessionClosed } from "./bindings/SessionClosed";
import type { SessionInfo } from "./bindings/SessionInfo";
import type { Severity } from "./bindings/Severity";
import type { Validation } from "./bindings/Validation";
import type { WorkspaceSettings } from "./bindings/WorkspaceSettings";
import type { WorkspaceStatus } from "./bindings/WorkspaceStatus";

export type {
  CommandError,
  Fix,
  FixAction,
  Grant,
  GrantDone,
  InitDone,
  Issue,
  NoteSaved,
  PermissionPage,
  ProjectDetails,
  ProjectMoved,
  ProjectSummary,
  RevokeDone,
  RootSaved,
  SwitchDone,
  SearchHit,
  SearchResults,
  SessionClosed,
  SessionInfo,
  Severity,
  Validation,
  WorkspaceSettings,
  WorkspaceStatus,
};

/** A command that failed, carrying the shell's structured error. */
export class EngineFailure extends Error {
  readonly kind: string;

  constructor(error: CommandError) {
    super(error.message);
    this.name = "EngineFailure";
    this.kind = error.kind;
  }
}

function looksLikeCommandError(value: unknown): value is CommandError {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as CommandError).kind === "string" &&
    typeof (value as CommandError).message === "string"
  );
}

/**
 * Is the desktop runtime present?
 *
 * Opening the Vite dev server in an ordinary browser gives the page but no shell, so the
 * interface says so instead of looking broken.
 */
export function isDesktopRuntime(): boolean {
  return typeof window !== "undefined" && "__TAURI_INTERNALS__" in window;
}

async function call<T>(command: string, args?: Record<string, unknown>): Promise<T> {
  try {
    return await invoke<T>(command, args);
  } catch (thrown) {
    // The shell returns a structured failure; anything else is a bug in the bridge and is
    // reported as one rather than flattened into the same shape.
    if (looksLikeCommandError(thrown)) throw new EngineFailure(thrown);
    throw new EngineFailure({
      kind: "Bridge",
      message: `unexpected failure from ${command}: ${String(thrown)}`,
    });
  }
}

export const engine = {
  workspace: {
    /** Where the workspace is, why that folder, and its projects. Creates the layout if missing. */
    status: () => call<WorkspaceStatus>("workspace_status"),
    /** The workspace configuration (`Config/workspace.toml`) and the folder in use. */
    config: () => call<WorkspaceSettings>("workspace_config"),
    /** A validation run. Always answers; `valid` says whether anything blocks. */
    validate: () => call<Validation>("workspace_validate"),
    /** Ranked matches in what may be read: Base, and with a project its Knowledge and Session. */
    search: (query: string, project: string | null, limit?: number) =>
      call<SearchResults>("workspace_search", { query, project, limit: limit ?? null }),
    /** Creates the standard layout and, if missing, the default configuration. */
    init: () => call<InitDone>("workspace_init"),
    /** Saves another workspace folder; ends an open chat session first. */
    setRoot: (path: string) => call<RootSaved>("workspace_set_root", { path }),
    /** Ignore AI_WORKSPACE_HOME until the app restarts and use the saved folder; ends an open chat session first. */
    switchToSaved: () => call<SwitchDone>("workspace_switch_to_saved"),
  },
  project: {
    show: (name: string) => call<ProjectDetails>("project_show", { name }),
    create: (name: string, description: string) =>
      call<ProjectDetails>("project_create", { name, description }),
    /** Sets the Ollama model a project uses; `null` returns it to the workspace default. */
    setModel: (name: string, model: string | null) =>
      call<ProjectDetails>("project_set_model", { name, model }),
    /** Moves a project into Projects/Archive/, ending an open chat session in it first (ADR-0015). */
    archive: (name: string) => call<ProjectMoved>("project_archive", { name }),
    /** Copies a project into `<folder>-clone`, display name "<name> (Clone)" (ADR-0015). */
    clone: (name: string) => call<ProjectDetails>("project_clone", { name }),
    /** Moves an archived project back into Projects/. */
    restore: (name: string) => call<ProjectMoved>("project_restore", { name }),
  },
  models: {
    /** Models Ollama has installed, for suggestions; empty when Ollama cannot be asked. */
    installed: () => call<string[]>("models_installed"),
  },
  permissions: {
    /** One page of a project's grants, optionally filtered by path. */
    list: (project: string, filter: string, page: number) =>
      call<PermissionPage>("permission_list", { project, filter, page, pageSize: null }),
    grant: (project: string, path: string) => call<GrantDone>("permission_grant", { project, path }),
    revoke: (project: string, path: string) => call<RevokeDone>("permission_revoke", { project, path }),
  },
  chat: {
    /** Opens a session in a project, closing any open one first. May take a while: it can start Ollama. */
    open: (project: string) => call<SessionInfo>("chat_open", { project }),
    /**
     * One message in the open session. `onPiece` gets each piece of the reply as the model
     * writes it (ADR-0013); the promise resolves with the whole reply.
     */
    send: (message: string, onPiece: (piece: string) => void = () => {}) => {
      const pieces = new Channel<string>(onPiece);
      return call<string>("chat_send", { message, onPiece: pieces });
    },
    close: () => call<SessionClosed | null>("chat_close"),
    /** The model's draft of a note about the open session; nothing is saved. */
    draftNote: () => call<string>("chat_draft_note"),
  },
  notes: {
    /** Saves a session note into the project's Session folder, on the person's say-so. */
    save: (project: string, text: string) => call<NoteSaved>("note_save", { project, text }),
  },
};

/** A failure's message, whatever was thrown. */
export function messageOf(thrown: unknown): string {
  if (thrown instanceof Error) return thrown.message;
  return String(thrown);
}
